/* Generated by scripts/build-service-worker.mjs. Aircraft API responses are never cached. */
const CACHE_PREFIX = 'skytrace-shell-';
const CACHE_NAME = `${CACHE_PREFIX}__SKYTRACE_VERSION__`;
const PRECACHE_URLS = __SKYTRACE_ASSETS__;
const PRECACHE_PATHS = new Set(PRECACHE_URLS);

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    try {
      await cache.addAll(PRECACHE_URLS.map((url) => new Request(url, { cache: 'reload' })));
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME)
      .map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.origin === self.location.origin && event.data?.type === 'SKIP_WAITING') void self.skipWaiting();
});

async function navigationResponse(request) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 3_000);
  try {
    const response = await fetch(request, { signal: controller.signal });
    if (response.ok) return response;
    if (response.status < 500) return response;
  } catch {
    // The precached HTML and its matching assets remain available without a connection.
  } finally {
    clearTimeout(timeout);
  }
  const shell = await caches.match('/index.html', { cacheName: CACHE_NAME });
  return shell ?? new Response('アプリを開けませんでした。インターネット接続を確認して再読み込みしてください。', {
    status: 503,
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  });
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin
    || url.pathname === '/api' || url.pathname.startsWith('/api/')) return;

  if (request.mode === 'navigate') {
    event.respondWith(navigationResponse(request));
    return;
  }

  if (url.search || !PRECACHE_PATHS.has(url.pathname)) return;
  event.respondWith((async () => {
    const cached = await caches.match(url.pathname, { cacheName: CACHE_NAME });
    return cached ?? fetch(request);
  })());
});
